-- TEST FIXTURE ONLY. This is not a production Supabase migration.
-- Apply only after explicitly confirming a separately approved, empty test
-- Supabase project and its project ref. These guards do not prove isolation.
-- No Auth users, memo data, legacy snapshots, keys, or approvals are imported.
-- Run as postgres. An error aborts this transaction; do not continue past it.

begin;

do $empty_test_database$
begin
  if to_regclass('public.memos') is not null
     or to_regclass('public.memo_restore_backups') is not null
     or to_regclass('public.memo_restore_audit') is not null
     or to_regclass('public.vault_notices') is not null
     or to_regclass('public.vault_instructors') is not null
     or to_regnamespace('byteback_recovery') is not null
     or to_regnamespace('byteback_devices') is not null then
    raise exception 'TEST_FIXTURE_REQUIRES_EMPTY_APPLICATION_DATABASE';
  end if;

  if not exists (select 1 from pg_roles where rolname = 'anon')
     or not exists (select 1 from pg_roles where rolname = 'authenticated')
     or not exists (select 1 from pg_roles where rolname = 'service_role') then
    raise exception 'TEST_FIXTURE_REQUIRES_SUPABASE_ROLES';
  end if;

  -- The unchanged recovery SQL explicitly calls extensions.digest/hmac.
  -- Do not relocate an existing extension or silently use a different schema.
  if exists (
    select 1 from pg_extension e
    join pg_namespace n on n.oid = e.extnamespace
    where e.extname = 'pgcrypto' and n.nspname <> 'extensions'
  ) then
    raise exception 'TEST_FIXTURE_REQUIRES_PGCRYPTO_IN_EXTENSIONS';
  end if;
end;
$empty_test_database$;

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

-- Stage-2 memo columns plus the public UUID required by the current HTTP API.
-- Keep owner_id independent of auth.users, as in the existing application.
create table public.memos (
  id bigint generated by default as identity primary key,
  public_id uuid unique not null default gen_random_uuid(),
  title text not null,
  content text,
  owner_id uuid,
  created_at timestamptz default now()
);

-- Exact legacy backup/audit column definitions from step10-private-memo-backup.
-- Both tables stay empty: do not run that file's production B-snapshot capture.
create table public.memo_restore_backups (
  backup_key text primary key check (backup_key = 'b_training_admin'),
  public_id uuid unique not null,
  owner_id uuid not null,
  title text not null,
  content text not null,
  content_sha256 text not null check (content_sha256 ~ '^[0-9a-f]{64}$'),
  source_commit text not null check (source_commit ~ '^[0-9a-f]{40}$'),
  backed_up_at timestamptz not null default now()
);

create table public.memo_restore_audit (
  audit_id uuid primary key default gen_random_uuid(),
  restored_at timestamptz not null default now(),
  actor_id uuid not null,
  memo_public_id uuid not null,
  backup_sha256 text not null check (backup_sha256 ~ '^[0-9a-f]{64}$'),
  action text not null check (action = 'memo_restore')
);

-- No instructor is granted here. Only an independently trusted test operator
-- may provision an instructor fixture for a separately approved notice test.
create table public.vault_instructors (
  user_id uuid primary key
);

create table public.vault_notices (
  public_id uuid primary key default gen_random_uuid(),
  title text not null,
  content text
);

alter table public.memos enable row level security;
alter table public.memo_restore_backups enable row level security;
alter table public.memo_restore_audit enable row level security;
alter table public.vault_instructors enable row level security;
alter table public.vault_notices enable row level security;

-- Browser roles cannot reach protected data directly. Also remove any default
-- service_role grants before assigning only the backend access required here.
revoke all on table public.memos, public.memo_restore_backups,
  public.memo_restore_audit, public.vault_instructors, public.vault_notices
from public, anon, authenticated, service_role;
revoke all on sequence public.memos_id_seq
from public, anon, authenticated, service_role;

grant usage on schema public to service_role;
grant select, insert, update, delete on table public.memos to service_role;
grant usage on sequence public.memos_id_seq to service_role;
grant select, update on table public.vault_notices to service_role;
grant select on table public.vault_instructors to service_role;

-- There are deliberately no direct service_role grants on backup/audit tables.
-- The existing postgres-owned recovery functions perform their checked access.
notify pgrst, 'reload schema';
commit;

-- Next, apply these existing files unchanged, in this order, to this same test DB:
-- 1. supabase/step10-created-memo-backups.sql (generates a new DB-only HMAC key)
-- 2. supabase/step10-verified-restore.sql
-- 3. supabase/step11-device-auth.sql
-- Do not apply step10-private-memo-backup.sql or production owner fixtures.
-- Create independent test users through test Supabase Auth, never by copying
-- production auth rows. Auth users may be created before or after this fixture.
